/**
 * Growing past the chart (apps/web/src/workspace/build/grow_acts.ts): hexes in empty slots are
 * made into sectors and generated by one request, and taken back by one Undo, also while the
 * job runs (findings/builder_grow_ready.md, contracts/b_builder.md "Make sectors and generate").
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { setBuildMap } from '../../apps/web/src/workspace/build/acts.ts';
import { generateGrowing, growUi } from '../../apps/web/src/workspace/build/grow_acts.ts';
import { useBuildStore } from '../../apps/web/src/workspace/build/seam.ts';
import { build } from '../../apps/web/src/workspace/build/state.ts';
import { clearToasts, toasts } from '../../apps/web/src/shell/toast.ts';

const SLOT_A = '~slot_3_-2';
const SLOT_B = '~slot_4_-2';
const ID_A = '~01M4GFABNQTCSR151Y18ANZN6Z';
const ID_B = '~01M4GFABNQTCSR151Y18ANZN70';

function deferred() {
    let resolve;
    let reject;
    const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
    promise.catch(() => undefined);
    return { promise, resolve, reject };
}

const tick = () => new Promise((resolve) => setTimeout(resolve, 0));

/** A store that records each request and answers when the test says. */
function stub() {
    const calls = { grow: [], undo: [] };
    const answers = { accepted: deferred(), finished: deferred(), undo: null, restore: null };
    const store = {
        universe: () => ({ id: 'u', name: 'U', truthVersion: 'v5' }),
        tick: () => 0,
        row: () => null,
        rows: () => [],
        generateGrowing(body, onProgress) {
            calls.grow.push({ body, onProgress });
            return { stop() { calls.stopped = true; }, accepted: answers.accepted.promise, finished: answers.finished.promise };
        },
        async undo(token) {
            calls.undo.push(token);
            if (answers.undo) throw answers.undo;
            return token.id === 'grow' ? answers.restore : null;
        },
    };
    return { store, calls, answers };
}

function setup() {
    const made = stub();
    const picked = [];
    useBuildStore(made.store);
    setBuildMap({ truth: () => null, sectorName: (slug) => slug, subsectorName: () => '', settings: () => null, select: (keys) => picked.push(keys) });
    growUi.names = {};
    growUi.error = '';
    growUi.busy = false;
    growUi.undoRunning = null;
    build.job = null;
    build.error = '';
    clearToasts();
    return { ...made, picked };
}

function teardown() {
    useBuildStore(null);
    setBuildMap(null);
    build.job = null;
    clearToasts();
}

test('one slot: one request carries the slot key and the new sector; nothing is sent without a name', async () => {
    const { calls, answers, picked } = setup();
    const keys = [SLOT_A + '/0101', SLOT_A + '/0102'];
    generateGrowing(keys);
    assert.equal(calls.grow.length, 0);
    assert.equal(growUi.error, 'To generate here, first name the new sector.');
    assert.equal(growUi.want, SLOT_A);
    growUi.names[SLOT_A] = '  Vell  ';
    generateGrowing(keys);
    assert.equal(calls.grow.length, 1);
    const body = calls.grow[0].body;
    assert.deepEqual(body.hexKeys, keys);
    assert.deepEqual(body.makeSectors, [{ name: 'Vell', slot: { x: 3, y: -2 } }]);
    assert.equal(body.filledToo, true);
    assert.equal(body.roll, 0);
    assert.equal(build.job.total, 2);
    answers.accepted.resolve({ sectors: [], keys: { [keys[0]]: ID_A + '/0101', [keys[1]]: ID_A + '/0102' }, undo: { id: 'grow' } });
    await tick();
    assert.deepEqual(picked, [[ID_A + '/0101', ID_A + '/0102']]);
    assert.deepEqual(growUi.names, {});
    answers.finished.resolve({ undo: { id: 'grow' }, progress: { total: 2, done: 2, failed: [], skipped: 0, state: 'done' } });
    await tick();
    assert.equal(build.job, null);
    assert.equal(toasts.length, 1);
    assert.equal(toasts[0].message, 'Generated 2 systems in the new sector Vell.');
    assert.equal(toasts[0].action.label, 'Undo');
    teardown();
});

test('two slots and a hex across a sector edge: still one request, one toast, one Undo', async () => {
    const { calls, answers } = setup();
    const keys = ['Spinward_Marches/3240', SLOT_A + '/0101', SLOT_B + '/0101'];
    growUi.names[SLOT_A] = 'Vell';
    growUi.names[SLOT_B] = 'Ostra';
    generateGrowing(keys);
    assert.equal(calls.grow.length, 1);
    assert.deepEqual(calls.grow[0].body.hexKeys, keys);
    assert.deepEqual(calls.grow[0].body.makeSectors, [{ name: 'Vell', slot: { x: 3, y: -2 } }, { name: 'Ostra', slot: { x: 4, y: -2 } }]);
    answers.accepted.resolve({ sectors: [], keys: { [keys[1]]: ID_A + '/0101', [keys[2]]: ID_B + '/0101' }, undo: { id: 'grow' } });
    answers.finished.resolve({ undo: { id: 'grow' }, progress: { total: 3, done: 3, failed: [], skipped: 0, state: 'done' } });
    await tick();
    assert.equal(toasts.length, 1);
    assert.equal(toasts[0].message, 'Generated 3 systems in 2 new sectors: Vell, Ostra.');
    // The Undo is one request, with the act's own token, and offers Restore when the store gives one back.
    answers.restore = { id: 'restore' };
    toasts[0].action.run();
    await tick();
    assert.deepEqual(calls.undo, [{ id: 'grow' }]);
    const undone = toasts[toasts.length - 1];
    assert.equal(undone.message, 'Removed the new sectors Vell and Ostra and every system generated in them.');
    assert.equal(undone.action.label, 'Restore');
    undone.action.run();
    await tick();
    assert.deepEqual(calls.undo, [{ id: 'grow' }, { id: 'restore' }]);
    assert.equal(toasts[toasts.length - 1].message, 'Restored the new sectors Vell and Ostra and their systems.');
    teardown();
});

test('no Restore when the store gives none back', async () => {
    const { answers } = setup();
    growUi.names[SLOT_A] = 'Vell';
    generateGrowing([SLOT_A + '/0101']);
    answers.accepted.resolve({ sectors: [], keys: {}, undo: { id: 'grow' } });
    answers.finished.resolve({ undo: { id: 'grow' }, progress: { total: 1, done: 1, failed: [], skipped: 0, state: 'done' } });
    await tick();
    toasts[0].action.run();
    await tick();
    assert.equal(toasts[toasts.length - 1].action, null);
    teardown();
});

test('Undo while the job runs: one request, the job ends stopped, and no "Generated" toast follows', async () => {
    const { calls, answers } = setup();
    growUi.names[SLOT_A] = 'Vell';
    generateGrowing([SLOT_A + '/0101', SLOT_A + '/0102', SLOT_A + '/0103']);
    assert.equal(growUi.undoRunning, null, 'no Undo before the server has answered');
    answers.accepted.resolve({ sectors: [], keys: {}, undo: { id: 'grow' } });
    await tick();
    calls.grow[0].onProgress({ total: 3, done: 1, failed: [], skipped: 0, state: 'running' });
    assert.equal(build.job.done, 1);
    assert.equal(typeof growUi.undoRunning, 'function');
    growUi.undoRunning();
    assert.equal(growUi.undoRunning, null);
    await tick();
    assert.deepEqual(calls.undo, [{ id: 'grow' }]);
    answers.finished.resolve({ undo: { id: 'grow' }, progress: { total: 3, done: 1, failed: [], skipped: 0, state: 'stopped' } });
    await tick();
    assert.equal(build.job, null);
    assert.deepEqual(toasts.map((item) => item.message), ['Removed the new sector Vell and every system generated in it.']);
    teardown();
});

test('a refusal is said in the server’s words; the selection and the names stay', async () => {
    const { answers, picked } = setup();
    growUi.names[SLOT_A] = 'Vell';
    generateGrowing([SLOT_A + '/0101']);
    const refused = new Error('That slot is in use. Choose another slot.');
    answers.accepted.reject(refused);
    answers.finished.reject(refused);
    await tick();
    assert.equal(growUi.error, 'That slot is in use. Choose another slot.');
    assert.equal(growUi.busy, false);
    assert.equal(build.job, null);
    assert.equal(build.error, '');
    assert.deepEqual(picked, []);
    assert.deepEqual(growUi.names, { [SLOT_A]: 'Vell' });
    assert.equal(toasts.length, 0);
    teardown();
});

test('an Undo the server refuses is said in its words', async () => {
    const { answers } = setup();
    growUi.names[SLOT_A] = 'Vell';
    generateGrowing([SLOT_A + '/0101']);
    answers.accepted.resolve({ sectors: [], keys: {}, undo: { id: 'grow' } });
    answers.finished.resolve({ undo: { id: 'grow' }, progress: { total: 1, done: 1, failed: [], skipped: 0, state: 'done' } });
    await tick();
    answers.undo = new Error('This sector changed. Reload it, then try again.');
    toasts[0].action.run();
    await tick();
    assert.equal(toasts[toasts.length - 1].message, 'This sector changed. Reload it, then try again.');
    teardown();
});
